def _combined(self) -> IntervalSide:
    left = self.left._values.reshape(-1)  # Flatten to 1D
    right = self.right._values.reshape(-1)  # Flatten to 1D

    if needs_i8_conversion(left.dtype):
        # Combining left and right by interleaving, then viewing as complex
        combined = np.empty((left.size + right.size,), dtype=left.dtype)
        combined[0::2] = left
        combined[1::2] = right
        comb = combined.view("complex128")
    else:
        comb = (np.array(left, dtype="complex128")) + (
            1j * np.array(right, dtype="complex128")
        )
    return comb

